import { useState } from "react";

export function Popover({
  label = "{{label}}",
  body = "{{body}}",
  variant = "{{variant}}",
  width = {{width}},
  accent = "{{accent}}",
  open: initialOpen = {{open}},
}) {
  const [open, setOpen] = useState(initialOpen);
  const panelStyle = {
    light: { background: "#FAF7F2", color: "#241430" },
    dark: { background: "#241430", color: "#FAF7F2" },
    accent: { background: "#FAF7F2", color: "#241430", borderWidth: 3 },
  }[variant] ?? {};
  return (
    <div style={{ position: "relative", minHeight: 220, padding: 22, boxSizing: "border-box" }}>
      <button type="button" onClick={() => setOpen((o) => !o)} aria-haspopup="dialog" aria-controls="popover-panel"
        aria-expanded={open ? "true" : "false"} style={{ font: "500 14px system-ui, sans-serif", padding: "9px 16px",
        borderRadius: 8, border: "1.5px solid #24143033", background: "#FAF7F2", color: "#241430", cursor: "pointer" }}>
        {label}
      </button>
      {open && (
        <div id="popover-panel" role="dialog" aria-labelledby="popover-panel-title" style={{ position: "absolute",
          top: 78, left: 22, borderRadius: 12, border: "1.5px solid", borderColor: accent, boxSizing: "border-box",
          boxShadow: "0 16px 32px rgba(36,20,48,.22)", padding: "14px 16px", width, ...panelStyle }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, marginBottom: 8 }}>
            <span id="popover-panel-title" style={{ fontWeight: 600, fontSize: 14 }}>{label}</span>
            <button type="button" aria-label="Close" onClick={() => setOpen(false)} style={{ border: "none",
              background: "transparent", color: "inherit", cursor: "pointer", padding: 4, borderRadius: 6 }}>
              <svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true"><path d="M1 1l10 10M11 1L1 11" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" /></svg>
            </button>
          </div>
          <p style={{ margin: 0, fontSize: 13, lineHeight: 1.5, opacity: .85 }}>{body}</p>
        </div>
      )}
    </div>
  );
}
